/**
 * Seed realistic fake patients generated by Synthea (synthetichealth/synthea).
 * The heavy 30MB sample bundles were distilled offline into
 * data/synthea-seed.json (6 patients × demographics + coverage + last 2
 * encounters + last 2 claims) so this runs with no Java and no download.
 * Idempotent: upserts by identifier, same as scripts/seed.ts.
 *
 *   npm run seed:synthea
 */
import fs from 'node:fs';
import path from 'node:path';
import type { Claim, Coverage, Encounter, Patient, Resource } from '@medplum/fhirtypes';
import { getStore, type FhirStore } from '@/lib/medplum.server';

const IDS = 'https://autonomous-backoffice.dev/synthea';

interface SeedClaim {
  id6: string;
  created?: string;
  total: number;
  procedure?: string;
  payer: string;
}
interface SeedEncounter {
  id6: string;
  type?: string;
  start?: string;
  end?: string;
}
interface SeedPatient {
  syntheaId: string;
  mrn: string;
  given: string[];
  family: string;
  gender?: string;
  birthDate?: string;
  phone?: string;
  city?: string;
  payer: string;
  encounters: SeedEncounter[];
  claims: SeedClaim[];
}

function payerName(raw: string): string {
  return raw === 'NO_INSURANCE' ? 'Self-pay' : raw;
}

async function upsert<T extends Resource>(store: FhirStore, resource: T, identifier: string): Promise<T> {
  const existing = (await store.search<T>(resource.resourceType, { identifier }))[0];
  if (existing) {
    console.log(`= ${resource.resourceType} ${identifier} already exists (${existing.id})`);
    return existing;
  }
  const created = await store.create<T>(resource);
  console.log(`+ ${resource.resourceType} ${identifier} (${created.id})`);
  return created;
}

async function main(): Promise<void> {
  const file = path.join(process.cwd(), 'data', 'synthea-seed.json');
  const seeds = JSON.parse(fs.readFileSync(file, 'utf8')) as SeedPatient[];
  const store = await getStore();
  console.log(`[synthea] seeding ${seeds.length} patients into ${store.mode} store`);

  for (const s of seeds) {
    const patient = await upsert<Patient>(
      store,
      {
        resourceType: 'Patient',
        identifier: [{ system: IDS, value: s.mrn }],
        name: [{ given: s.given, family: s.family }],
        gender: s.gender as Patient['gender'],
        birthDate: s.birthDate,
        telecom: s.phone ? [{ system: 'phone', value: s.phone, use: 'home' }] : undefined,
        address: s.city ? [{ city: s.city }] : undefined,
      },
      s.mrn,
    );
    const patientRef = { reference: `Patient/${patient.id}` };

    if (s.payer !== 'NO_INSURANCE') {
      await upsert<Coverage>(
        store,
        {
          resourceType: 'Coverage',
          identifier: [{ system: IDS, value: `SYN-COV-${s.syntheaId.slice(0, 6)}` }],
          status: 'active',
          beneficiary: patientRef,
          subscriberId: s.mrn.replace('MRN-', 'MEM-'),
          payor: [{ display: payerName(s.payer) }],
        },
        `SYN-COV-${s.syntheaId.slice(0, 6)}`,
      );
    }

    // Synthea's deterministic ids share prefixes within a patient, so add an
    // index to keep identifiers unique (bare value kept for i=0 so reruns
    // don't duplicate resources created before this fix).
    for (const [i, e] of s.encounters.entries()) {
      const value = i === 0 ? `SYN-ENC-${e.id6}` : `SYN-ENC-${e.id6}-${i}`;
      await upsert<Encounter>(
        store,
        {
          resourceType: 'Encounter',
          identifier: [{ system: IDS, value }],
          status: 'finished',
          class: { code: 'AMB', display: 'ambulatory' },
          type: e.type ? [{ text: e.type }] : undefined,
          subject: patientRef,
          period: { start: e.start, end: e.end },
        },
        value,
      );
    }

    // Newest claim lands as draft ("Ready" on the board — triage bait);
    // the older one as active ("Submitted").
    for (const [i, c] of s.claims.entries()) {
      const value = i === 0 ? `SYN-CLM-${c.id6}` : `SYN-CLM-${c.id6}-${i}`;
      await upsert<Claim>(
        store,
        {
          resourceType: 'Claim',
          identifier: [{ system: IDS, value }],
          status: i === 0 ? 'draft' : 'active',
          type: { coding: [{ system: 'http://terminology.hl7.org/CodeSystem/claim-type', code: 'professional' }] },
          use: 'claim',
          patient: patientRef,
          created: c.created ?? new Date().toISOString(),
          provider: { display: 'Lakeside Family Clinic' },
          priority: { coding: [{ code: 'normal' }] },
          insurance: [{ sequence: 1, focal: true, coverage: { display: payerName(c.payer) } }],
          item: [{ sequence: 1, productOrService: { text: c.procedure ?? 'Professional service' } }],
          total: { value: c.total, currency: 'USD' },
        },
        value,
      );
    }
  }
  console.log('[synthea] done.');
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});
